function extract($, ctx) {
  const items = [];

  $('.menu-section').each((_, secEl) => {
    const $sec = $(secEl);
    const sectionTitle = cleanText($sec.find('.menu-section-title').text()) || null;

    $sec.find('.menu-item').each((_, itmEl) => {
      const $itm = $(itmEl);

      const nameRaw = $itm.find('.menu-item-title').text();
      const name = cleanText(nameRaw);
      if (!name) return; // skip items with empty name

      const descRaw = $itm.find('.menu-item-description').text();
      const description = cleanText(descRaw) || null;

      // Try price from top element, fall back to bottom
      let price = null;
      const priceTopTxt = $itm.find('.menu-item-price-top').text();
      price = parsePrice(priceTopTxt);
      if (price === null) {
        const priceBottomTxt = $itm.find('.menu-item-price-bottom').text();
        price = parsePrice(priceBottomTxt);
      }

      items.push({
        section: sectionTitle,
        name,
        description,
        price
      });
    });
  });

  // Remove exact duplicates (e.g., mobile/desktop copies)
  const seen = new Set();
  const deduped = items.filter(item => {
    const key = JSON.stringify(item);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  return deduped;
}
